let input = msg.payload;

if (typeof input === "string") {
    try {
        input = JSON.parse(input);
    } catch (err) {
        node.error("Request JSON ไม่ถูกต้อง", msg);
        return null;
    }
}

if (!input || !input.item_id) {
    node.error("คำขอต้องมี item_id", msg);
    return null;
}

const shelfId = input.shelf_id || "SHELF_A";
let slotId = input.slot_id;

// ถ้าไม่ระบุ slot_id ให้เลือกช่อง EMPTY แรกจากสถานะล่าสุดที่ Unity ส่งมา
if (!slotId) {
    const cachedSlots = flow.get("shelf_slots_" + shelfId) || [];
    const freeSlot = cachedSlots.find(s => s.free === true && s.state === "EMPTY");

    if (!freeSlot) {
        node.warn("ไม่พบช่องว่าง หรือยังไม่ได้รับ state/slots จาก Unity");
        return null;
    }

    slotId = freeSlot.slot_id;
}

const requestId = "REQ-" + Date.now();
const pending = {
    request_id: requestId,
    item_id: String(input.item_id),
    slot_id: String(slotId),
    shelf_id: String(shelfId)
};

flow.set("pending_" + requestId, pending);

msg.topic = "dgt/warehouse/shelf/" + shelfId + "/command/check";
msg.qos = 1;
msg.retain = false;
msg.payload = JSON.stringify({
    request_id: requestId,
    slot_id: String(slotId)
});

node.status({fill: "blue", shape: "dot", text: "check " + slotId});
return msg;

const feedback = msg.payload || {};
const requestId = feedback.request_id;
const key = "pending_" + requestId;
const pending = flow.get(key);

if (!pending) {
    return [null, {
        payload: {
            result: "IGNORED",
            reason: "PENDING_REQUEST_NOT_FOUND",
            feedback: feedback
        }
    }];
}

if (feedback.free !== true || feedback.state !== "EMPTY") {
    flow.set(key, null);

    node.status({fill: "yellow", shape: "ring", text: pending.slot_id + " not free"});

    return [null, {
        payload: {
            result: "REJECTED",
            reason: "SLOT_NOT_EMPTY",
            request: pending,
            feedback: feedback
        }
    }];
}

msg.topic = "dgt/warehouse/shelf/" + pending.shelf_id + "/command/place";
msg.qos = 1;
msg.retain = false;
msg.payload = JSON.stringify({
    request_id: pending.request_id,
    item_id: pending.item_id,
    slot_id: pending.slot_id
});

node.status({fill: "green", shape: "dot", text: "place " + pending.slot_id});
return [msg, null];

const data = msg.payload || {};

if (data.request_id) {
    flow.set("pending_" + data.request_id, null);
}

const success = data.status === "PLACED";

msg.payload = [
    {
        success: success,
        status: String(data.status || "UNKNOWN"),
        message: String(data.message || "NONE"),
        item_id: String(data.item_id || "NONE"),
        request_id: String(data.request_id || "NONE"),
        source_timestamp: String(data.timestamp || new Date().toISOString())
    },
    {
        shelf_id: String(data.shelf_id || "SHELF_A"),
        slot_id: String(data.slot_id || "UNKNOWN")
    }
];

node.status({
    fill: success ? "green" : "red",
    shape: success ? "dot" : "ring",
    text: String(data.status || "UNKNOWN")
});

return msg;

const data = msg.payload || {};

if (!Array.isArray(data.slots)) {
    node.warn("state/slots ไม่มี slots array");
    return null;
}

const shelfId = String(data.shelf_id || "SHELF_A");
flow.set("shelf_slots_" + shelfId, data.slots);

const sourceTimestamp = String(data.timestamp || new Date().toISOString());
const outputMessages = [];

for (const slot of data.slots) {
    outputMessages.push({
        payload: [
            {
                state: String(slot.state || "UNKNOWN"),
                item_id: String(slot.item_id || "NONE"),
                free: slot.free === true,
                source_timestamp: sourceTimestamp
            },
            {
                shelf_id: shelfId,
                slot_id: String(slot.slot_id || "UNKNOWN")
            }
        ]
    });
}

node.status({fill: "green", shape: "dot", text: data.slots.length + " slots"});

// ส่งหลาย Message ออกจาก Output เดียว เพื่อเขียน 1 จุดต่อ 1 ช่อง
return [outputMessages];
